import betterTailwindcss from 'eslint-plugin-better-tailwindcss';
import * as astroParser from 'astro-eslint-parser';
import * as mdx from 'eslint-plugin-mdx';
import tsParser from '@typescript-eslint/parser';

/**
 * ESLint here exists for ONE job: catching Tailwind class problems that
 * `astro check` and Prettier cannot see.
 *
 * - `astro check` type-checks; a class string is just a string to it.
 * - `prettier-plugin-tailwindcss` only *sorts* classes, it never rewrites them.
 *
 * So `max-w-[680px]` (which is exactly `max-w-170` on the v4 spacing scale)
 * sails through both. The Tailwind language server flags it in the editor, but
 * editor diagnostics are invisible to CI and to coding agents. This config
 * turns that same diagnostic into a command anyone (and any agent) can run.
 *
 * Deliberately NOT a general-purpose JS/TS lint setup. Only the
 * better-tailwindcss rules are on; no `eslint:recommended`, no type-aware
 * rules. Keep it that way unless there is a reason to broaden it.
 *
 * Two rules stay OFF on purpose:
 * - `enforce-consistent-class-order` fights `prettier-plugin-tailwindcss`.
 *   They sort differently, so with both on the two tools undo each other on
 *   every save. Prettier owns class order here. (Verified: Prettier reports
 *   MapMoveResults.astro as correctly formatted while the rule reports 33
 *   order violations on that same file.) Same reasoning for
 *   `enforce-consistent-line-wrapping`.
 * - `enforce-logical-properties` rewrites every `ml-`/`mr-` to `ms-`/`me-`,
 *   760 findings of RTL preparation on an English-only site.
 */

const CLASS_RULES = {
  // The one that started this: `max-w-[680px]` -> `max-w-170`,
  // `h-[30px]` -> `h-7.5`. Autofixable.
  'better-tailwindcss/enforce-canonical-classes': 'error',
  // Real bugs, not style: two classes fighting over the same property.
  'better-tailwindcss/no-conflicting-classes': 'error',
  'better-tailwindcss/no-duplicate-classes': 'error',
  'better-tailwindcss/no-deprecated-classes': 'error',
  // Collapsing two classes into one leaves a double space behind. On without
  // this the autofix produces its own lint-clean-but-scruffy output.
  'better-tailwindcss/no-unnecessary-whitespace': 'error',
  // The highest-value rule here. A misspelt class compiles to nothing and
  // fails silently: `flex-co` still renders, just as a row. Nothing else in
  // the toolchain can see that. `ignore` lists the classes that are genuinely
  // ours (hand-written CSS, plugin output, JS hooks) rather than typos --
  // keep it exact-anchored so a real typo can never slip through a loose
  // prefix match.
  'better-tailwindcss/no-unknown-classes': [
    'error',
    {
      ignore: [
        '^badge$', // .badge / .badge .text, styled in about-this-site/bento.astro
        '^text$',
        '^not-prose$', // @tailwindcss/typography
        '^modal-', // modal-popup.astro's own CSS
        '^material-symbols-outlined$', // icon font
        '^quiz-stepper$', // JS hooks, not styling
        '^quiz-result-card$',
      ],
    },
  ],
  // Both report zero across src/, so they cost nothing and close the door on
  // `"px-" + size` style dynamic classes, which Tailwind cannot see at build
  // time and which therefore never generate CSS.
  'better-tailwindcss/no-concatenated-classes': 'error',
  'better-tailwindcss/enforce-consistent-variant-order': 'error',
};

const SETTINGS = {
  'better-tailwindcss': {
    // Where Tailwind's design system is defined, so the plugin knows the
    // spacing scale and the `--color-quiz-*` theme tokens.
    entryPoint: 'src/styles/global.css',
    // Required for px -> spacing-scale conversion. Without it the plugin will
    // not know that `max-w-[680px]` is 42.5rem is `max-w-170`, and arbitrary
    // px values pass silently.
    rootFontSize: 16,
  },
};

export default [
  {
    ignores: [
      'dist/**',
      '.astro/**',
      '.netlify/**',
      'node_modules/**',
      'public/**',
      'email-automation/**',
      'temp/**',
    ],
  },
  {
    files: ['**/*.{ts,tsx,js,jsx,mjs}'],
    languageOptions: {
      parser: tsParser,
      parserOptions: {
        ecmaVersion: 'latest',
        sourceType: 'module',
        ecmaFeatures: { jsx: true },
      },
    },
    plugins: { 'better-tailwindcss': betterTailwindcss },
    settings: SETTINGS,
    rules: CLASS_RULES,
  },
  {
    files: ['**/*.astro'],
    languageOptions: {
      parser: astroParser,
      parserOptions: {
        parser: tsParser,
        extraFileExtensions: ['.astro'],
      },
    },
    plugins: { 'better-tailwindcss': betterTailwindcss },
    settings: SETTINGS,
    rules: CLASS_RULES,
