#!/usr/bin/env node
/**
 * Tailwind class linter. Two modes, one ESLint config (eslint.config.js).
 *
 *   node scripts/tw-lint.mjs         # lint all of src/
 *   node scripts/tw-lint.mjs --hook  # Claude Code PostToolUse hook (stdin JSON)
 *
 * There was a third mode, `--changed`, which linted only files changed vs HEAD.
 * It existed to police a backlog while the rest of the site was still dirty.
 * All of `src/` is clean now, so whole-src is the gate and a second, weaker
 * command is just a thing to get wrong.
 *
 * Why this exists: `astro check` type-checks, so a class string is just a
 * string to it, and prettier-plugin-tailwindcss only sorts classes. Neither can
 * see that `max-w-[680px]` is exactly `max-w-170`. The Tailwind language server
 * can, but editor diagnostics are invisible to CI and to coding agents.
 */

import { ESLint } from 'eslint';
import { existsSync } from 'node:fs';

const LINTABLE = /\.(astro|tsx|jsx|ts|js|mjs|mdx)$/;

async function lint(files) {
  const eslint = new ESLint();
  const results = await eslint.lintFiles(files);

  // eslint-mdx still cannot parse a handful of our MDX files. The frontmatter
  // half of that is fixed (see .remarkrc.mjs); what remains is an upstream bug
  // in eslint-mdx 3.8.1: a JSX attribute whose quoted value spans multiple
  // lines corrupts its offset tracking, and it then asserts on a LATER element
  // in the same file. That is its limitation, not a Tailwind problem, so it
  // must not fail the check -- but those files do go unchecked, so count them
  // and say so rather than hiding them.
  let unparsed = 0;
  for (const r of results) {
    if (!r.filePath.endsWith('.mdx')) continue;
    const fatal = r.messages.filter((m) => m.fatal);
    if (fatal.length === 0) continue;
    unparsed++;
    r.messages = r.messages.filter((m) => !m.fatal);
    r.errorCount -= fatal.length;
    r.fatalErrorCount = 0;
  }

  const formatter = await eslint.loadFormatter('stylish');
  return {
    output: await formatter.format(results),
    errors: results.reduce((n, r) => n + r.errorCount, 0),
    unparsed,
  };
}

const mode = process.argv[2];

if (mode === '--hook') {
  // PostToolUse: stdin carries the hook payload. Exit 2 puts stderr in front of
  // the model as a blocking error; anything else is invisible to it.
  const payload = JSON.parse(
    await new Promise((resolve) => {
      let s = '';
      process.stdin
        .on('data', (d) => (s += d))
        .on('end', () => resolve(s || '{}'));
    })
  );
  const file = payload?.tool_input?.file_path;
  if (!file || !LINTABLE.test(file) || !existsSync(file)) process.exit(0);

  const { output, errors } = await lint([file]);
  if (errors > 0) {
    process.stderr.write(
      `Tailwind class issues in the file you just wrote. Fix these before moving on:\n\n${output}\n` +
        `Most are autofixable: npx eslint --fix ${file}\n`
    );
    process.exit(2);
  }
  process.exit(0);
}

const { output, errors, unparsed } = await lint(['src']);
if (output) console.log(output);
if (unparsed > 0) {
  console.log(
    `Note: ${unparsed} MDX file(s) could not be parsed by eslint-mdx and were NOT checked.`
  );
}
process.exit(errors > 0 ? 1 : 0);
