import prettier from 'eslint-config-prettier';
import { fileURLToPath } from 'node:url';
import { includeIgnoreFile } from '@eslint/compat';
import betterTailwindcss from 'eslint-plugin-better-tailwindcss';
import js from '@eslint/js';
import svelte from 'eslint-plugin-svelte';
import { defineConfig } from 'eslint/config';
import globals from 'globals';
import ts from 'typescript-eslint';
import svelteConfig from './svelte.config.js';

const gitignorePath = fileURLToPath(new URL('./.gitignore', import.meta.url));

/**
 * Tailwind class checking. Nothing else in the toolchain can see inside a
 * `class="…"` string: `svelte-check` type-checks, so a class list is just a
 * string to it, and `prettier-plugin-tailwindcss` only *sorts* classes, it
 * never rewrites them. So `bg-opacity-50` — a Tailwind v3 class that v4 dropped
 * entirely — compiled to nothing and rendered an opaque modal backdrop while
 * `check`, `lint` and `build` all passed. These rules turn the Tailwind
 * language server's editor-only diagnostics into something CI and coding agents
 * can run.
 *
 * Two rules stay OFF on purpose:
 * - `enforce-consistent-class-order` sorts differently from
 *   `prettier-plugin-tailwindcss`, so with both on the two tools undo each
 *   other on every save. Prettier owns class order here.
 * - `enforce-consistent-line-wrapping`, same reason.
 */
const TAILWIND_RULES = {
	// Arbitrary values that already sit on the scale (`h-[30px]` -> `h-7.5`) and
	// collapsible pairs (`h-4 w-4` -> `size-4`). Autofixable.
	'better-tailwindcss/enforce-canonical-classes': 'error',
	// Real bugs, not style: two classes fighting over the same property.
	'better-tailwindcss/no-conflicting-classes': 'error',
	'better-tailwindcss/no-duplicate-classes': 'error',
	// Catches the v3 leftovers, e.g. `rounded` -> `rounded-sm` after v4's
	// radius-scale rename.
	'better-tailwindcss/no-deprecated-classes': 'error',
	// Collapsing two classes into one leaves a double space behind.
	'better-tailwindcss/no-unnecessary-whitespace': 'error',
	// The highest-value rule. A class that Tailwind doesn't generate compiles to
	// nothing and fails silently — `flex-co` still renders, just as a row. The
	// `ignore` list is the classes that are genuinely ours (hand-written CSS in
	// a component's `<style>` block, or JS hooks); keep the patterns
	// exact-anchored so a real typo can never slip through a loose prefix match.
	'better-tailwindcss/no-unknown-classes': [
		'error',
		{
			ignore: [
				// CategoryDropdown.svelte `<style>` block
				'^category-dropdown$',
				'^category-dropdown-menu$',
				'^category-trigger$',
				'^category-list$',
				'^category-option$',
				// CategoryFilter.svelte — a JS hook, matched by `closest()`
				'^category-filter-container$',
				// Page-level `<style>` blocks
				'^expenses-page$',
				'^spending-page$',
				'^hierarchy-editor$',
				'^receipt-scroll-container$'
			]
		}
	],
	// Closes the door on `"px-" + size` dynamic classes, which Tailwind cannot
	// see at build time and which therefore never generate any CSS.
	'better-tailwindcss/no-concatenated-classes': 'error',
	'better-tailwindcss/enforce-consistent-variant-order': 'error'
};

const TAILWIND_SETTINGS = {
	'better-tailwindcss': {
		// Where the design system is defined, so the plugin knows our spacing
		// scale and theme tokens.
		entryPoint: 'src/app.css',
		// Required for px -> spacing-scale conversion. Without it the plugin does
		// not know that `max-w-[680px]` is 42.5rem is `max-w-170`, and arbitrary
		// px values pass silently.
		rootFontSize: 16
	}
};

