/**
 * Test Suite for Email Attachment Filtering
 *
 * Tests for:
 * - #{#eaf1a} Filter attachments by supported MIME types
 * - #{#eaf2a} Skip inline attachments
 * - #{#eaf3a} Validate OCR results before receipt insert
 * - #{#eaf4a} Process all valid attachments (structural — tested via integration assertions)
 * - #{#eaf5a} Prioritize attachments over email body text
 *
 * Authority: system (eaf1a-eaf3a), developer (eaf4a-eaf5a)
 * Priority: Critical / High
 */

import { describe, it, expect } from 'vitest';
import {
	isSupportedReceiptType,
	isInlineAttachment,
	hasUsableOcrData,
	hasSupportedAttachments,
	SUPPORTED_RECEIPT_TYPES,
	EXTENSION_TO_MIME
} from './attachmentFiltering';
import type { AttachmentMetadata } from './attachmentFiltering';

// ─────────────────────────────────────────────
// #{#eaf1a} Filter Attachments by Supported MIME Types
// ─────────────────────────────────────────────
describe('#{#eaf1a} - Filter Attachments by Supported MIME Types', () => {
	describe('SUPPORTED_RECEIPT_TYPES constant', () => {
=== 100-115 notify.test ===
		vi.stubGlobal('fetch', fetchMock);

		await sendNotificationEmail('k', 'user@example.com', 'success', 't', 'm', 's');

		const body = JSON.parse((fetchMock.mock.calls[0][1] as RequestInit).body as string);
		expect(body.from).toBe('Expense Tracker <receipts@verified.example.com>');
	});

	it('resolveFromAddress prefers config and never yields an empty domain', () => {
		delete g.Deno;
		// No env configured → default must still be a complete address, never "test@".
		const fallback = resolveFromAddress();
		expect(fallback).toMatch(/@[^>\s]+\.[^>\s]+/);

		mockDenoEnv({ RESEND_FROM_EMAIL: 'A <a@b.com>' });
		expect(resolveFromAddress()).toBe('A <a@b.com>');

